'use strict';
const t=v=>String(v??'').normalize('NFKC').trim();const input=$input.first()?.json||{};const actor=t(input.telegramActorId||input.telegramNumericUserId);if(!/^\d+$/.test(actor)||Number(actor)<=0)throw new Error('trusted_numeric_telegram_actor_required');
const username=t(input.currentUsername||input.telegramUsername).replace(/^@+/,'').toLowerCase();if(username&&!/^[a-z0-9_]{1,64}$/.test(username))throw new Error('telegram_username_invalid');
const safe={...input};for(const k of ['message','callback_query','edited_message','telegramUserId'])delete safe[k];return [{json:{...safe,telegramActorId:actor,currentUsername:username,telegramUsername:username,timeZone:t(input.timeZone||input.timezone)||'Asia/Novosibirsk'}}];

'use strict';
const x=$input.first()?.json||{};const t=v=>String(v??'').normalize('NFKC').trim();if(x.identityAuthorityVerified!==true)throw new Error('postgres_identity_authority_not_verified');
const conflict=['identity_conflict','migration_review_required'].includes(t(x.identityStatus));if(conflict)return [{json:{...x,identityUsable:false,identityClaimsVerified:false,registrationState:'failed_review',identityAuthorityBoundaryVersion:'chelsea_postgres_identity_boundary_v2'}}];
const actor=t(x.telegramActorId||x.telegramUserId);if(!/^\d+$/.test(actor)||Number(actor)<=0)throw new Error('postgres_identity_boundary_numeric_actor_required');
if(!/^tgactor_[a-f0-9]{64}$/.test(t(x.principalKey))||!/^actor_[a-f0-9]{32}$/.test(t(x.storageUsername))||!/^[0-9a-f]{8}-[0-9a-f]{4}-5[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(t(x.principalUuid))||t(x.identitySchemaVersion)!=='chelsea_actor_identity_v3')throw new Error('postgres_identity_boundary_contract_rejected');
const isStart=/^\/start(?:\s|$)/i.test(t(x.messageText||x.question));let failure=t(x.failureCode);if(t(x.registrationState)==='new'&&!isStart)failure='registration_requires_start';
return [{json:{...x,telegramActorId:actor,telegramUserId:actor,actorPrincipalKey:t(x.principalKey),immutableStorageUsername:t(x.storageUsername),identityClaimsVerified:true,identityUsable:x.identityUsable===true&&t(x.registrationState)==='ready'&&x.identityStorageMigrationRequired!==true,failureCode:failure,identityAuthorityBoundaryVersion:'chelsea_postgres_identity_boundary_v2',identityResolvedAtIso:new Date().toISOString()}}];
